import java.nio.charset.*;class Solution{record Message(String user,String text){Message{if(!user.matches("[A-Za-z0-9_]{1,20}")||text.isBlank())throw new IllegalArgumentException("message");}}static byte[]encode(Message value){byte[]data=("1|"+value.user()+"|"+value.text()).getBytes(StandardCharsets.UTF_8);if(data.length>4096)throw new IllegalArgumentException("too large");return data;}static Message decode(byte[]data){if(data.length>4096)throw new IllegalArgumentException("too large");String[]parts=new String(data,StandardCharsets.UTF_8).split("\\|",3);if(parts.length!=3||!parts[0].equals("1"))throw new IllegalArgumentException("version");return new Message(parts[1],parts[2]);}}
